const defRows = `-- name: DefRows :many

SELECT d.kind, d.id, d.path, d.head::bigint AS head, d.repo_sha, d.repo_content_sha, d.ever_shipped, d.retired_at,
 r.revision::bigint AS revision, r.parent, r.content, r.content_sha, r.repo_base, r.source, r.actor_kind,
 r.by_email, r.by_execution, r.directed_by, r.message, r.at
FROM definition d JOIN definition_revision r ON r.kind=d.kind AND r.id=d.id
 AND r.revision = CASE WHEN $1::int > 0 THEN $1::int ELSE d.head END
WHERE ($2::text IS NULL OR d.kind=$2::text) AND ($3::text IS NULL OR d.id=$3::text)
 AND (NOT $4::boolean OR d.deleted_at IS NULL) AND (NOT $5::boolean OR d.retired_at IS NULL)
ORDER BY d.kind, d.id
`

type DefRowsParams struct {
	Revision int32
	Kind     *string
	ID       *string
	Live     bool
	Current  bool
}

type DefRowsRow struct {
	Kind           string
	ID             string
	Path           string
	Head           int64
	RepoSha        *string
	RepoContentSha *string
	EverShipped    bool
	RetiredAt      *time.Time
	Revision       int64
	Parent         *int32
	Content        string
	ContentSha     string
	RepoBase       *string
	Source         string
	ActorKind      string
	ByEmail        *string
	ByExecution    *string
	DirectedBy     *string
	Message        string
	At             time.Time
}

// Definitions (definitions.go, definitions_write.go, definitions_usage.go), project definitions and access
// (project_definitions.go, project_access.go): docs/designs/fleet-definition-editors.md.
// Definitions with one revision each: the head, or revision when above 0; kind and id optional; live leaves out deleted
// ones, current retired ones.
func (q *Queries) DefRows(ctx context.Context, arg DefRowsParams) ([]DefRowsRow, error) {
	rows, err := q.db.Query(ctx, defRows,
		arg.Revision,
		arg.Kind,
		arg.ID,
		arg.Live,
		arg.Current,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DefRowsRow
	for rows.Next() {
		var i DefRowsRow
		if err := rows.Scan(
			&i.Kind,
			&i.ID,
			&i.Path,
			&i.Head,
			&i.RepoSha,
			&i.RepoContentSha,
			&i.EverShipped,
			&i.RetiredAt,
			&i.Revision,
			&i.Parent,
			&i.Content,
			&i.ContentSha,
			&i.RepoBase,
			&i.Source,
			&i.ActorKind,
			&i.ByEmail,
			&i.ByExecution,
			&i.DirectedBy,
			&i.Message,
			&i.At,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

