const defUsage = `-- name: DefUsage :many
SELECT coalesce(d->>'id','')::text AS id,
 coalesce(CASE WHEN (d->>'revision') ~ '^[0-9]+$' THEN (d->>'revision')::bigint END, -1)::bigint AS rev,
 GROUPING(CASE WHEN (d->>'revision') ~ '^[0-9]+$' THEN (d->>'revision')::bigint END)::int AS total,
 count(*)::bigint AS runs, (count(*) FILTER (WHERE e.state='succeeded'))::bigint AS succeeded,
 coalesce((percentile_disc(0.5) WITHIN GROUP (ORDER BY coalesce(t.wall_ms, CASE WHEN e.started_at IS NOT NULL AND e.ended_at IS NOT NULL THEN greatest(0, (extract(epoch FROM e.ended_at - e.started_at)*1000)::bigint) END)))::bigint, -1)::bigint AS median,
 coalesce(sum(coalesce(t.tokens_input,0)+coalesce(t.tokens_output,0)),0)::bigint AS tokens
FROM execution e CROSS JOIN LATERAL jsonb_array_elements(e.definitions) d LEFT JOIN execution_totals t ON t.execution_id=e.id
WHERE e.definitions @> $1::jsonb AND d->>'kind'=$2::text AND ($3::text='' OR d->>'id'=$3::text)
 AND coalesce((d->>'draft')::boolean,false)=false AND coalesce(d->>'revision','') ~ '^[0-9]+$'
 AND coalesce(e.started_at, e.updated_at) >= now() - make_interval(days => $4::int)
GROUP BY d->>'id', ROLLUP (CASE WHEN (d->>'revision') ~ '^[0-9]+$' THEN (d->>'revision')::bigint END)
`

type DefUsageParams struct {
	Pin  []byte
	Kind string
	ID   string
	Days int32
}

type DefUsageRow struct {
	ID        string
	Rev       int64
	Total     int32
	Runs      int64
	Succeeded int64
	Median    int64
	Tokens    int64
}

// Runs, successes, median wall time and tokens of the executions that pinned a saved revision of kind/id (id ” for every
// definition of the kind) in the last days, per definition (total=1) and per revision; -1 stands for no revision (a total)
// and no median.
func (q *Queries) DefUsage(ctx context.Context, arg DefUsageParams) ([]DefUsageRow, error) {
	rows, err := q.db.Query(ctx, defUsage,
		arg.Pin,
		arg.Kind,
		arg.ID,
		arg.Days,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DefUsageRow
	for rows.Next() {
		var i DefUsageRow
		if err := rows.Scan(
			&i.ID,
			&i.Rev,
			&i.Total,
			&i.Runs,
			&i.Succeeded,
			&i.Median,
			&i.Tokens,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const defUsageRecent = `-- name: DefUsageRecent :many
WITH recent AS (
 SELECT x.id, x.state, x.started_at, x.ended_at, x.definitions FROM execution x
 WHERE x.started_at >= now() - make_interval(days => $2::int) AND jsonb_typeof(x.definitions) = 'array' AND x.definitions <> '[]'::jsonb
 UNION ALL
 SELECT x.id, x.state, x.started_at, x.ended_at, x.definitions FROM execution x
 WHERE x.started_at IS NULL AND x.updated_at >= now() - make_interval(days => $2::int) AND jsonb_typeof(x.definitions) = 'array' AND x.definitions <> '[]'::jsonb
)
SELECT coalesce(d->>'kind','')::text AS kind, coalesce(d->>'id','')::text AS id,
 count(*)::bigint AS runs, (count(*) FILTER (WHERE e.state='succeeded'))::bigint AS succeeded,
 coalesce((percentile_disc(0.5) WITHIN GROUP (ORDER BY coalesce(t.wall_ms, CASE WHEN e.started_at IS NOT NULL AND e.ended_at IS NOT NULL THEN greatest(0, (extract(epoch FROM e.ended_at - e.started_at)*1000)::bigint) END)))::bigint, -1)::bigint AS median,
 coalesce(sum(coalesce(t.tokens_input,0)+coalesce(t.tokens_output,0)),0)::bigint AS tokens
FROM recent e CROSS JOIN LATERAL jsonb_array_elements(e.definitions) d
LEFT JOIN execution_totals t ON t.execution_id=e.id
WHERE d->>'kind' = ANY($1::text[])
 AND coalesce((d->>'draft')::boolean,false)=false AND coalesce(d->>'revision','') ~ '^[0-9]+$'
GROUP BY d->>'kind', d->>'id'
`

type DefUsageRecentParams struct {
	Kinds []string
	Days  int32
}

type DefUsageRecentRow struct {
	Kind      string
	ID        string
	Runs      int64
	Succeeded int64
	Median    int64
	Tokens    int64
}

// DefUsage's totals for every definition of the kinds in one pass (Library's tree, system_changes): the last days'
// executions are chosen by plain timestamp comparisons on execution_started_at, which RLS lets an index serve (a
// jsonb containment is not leakproof, so DefUsage's pin cannot start from execution_definitions under RLS); a run that
// has not started counts by its last update, as in DefUsage.
func (q *Queries) DefUsageRecent(ctx context.Context, arg DefUsageRecentParams) ([]DefUsageRecentRow, error) {
	rows, err := q.db.Query(ctx, defUsageRecent, arg.Kinds, arg.Days)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DefUsageRecentRow
	for rows.Next() {
		var i DefUsageRecentRow
		if err := rows.Scan(
			&i.Kind,
			&i.ID,
			&i.Runs,
			&i.Succeeded,
			&i.Median,
			&i.Tokens,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

